package io.github.diodeme.ji.provider.http;

import java.net.URI;
import java.util.ArrayList;
import java.util.List;

/** Protocol resource resolution for service roots and API prefixes. */
public final class ProviderEndpoints {
    private ProviderEndpoints() {}

    public static URI v1(URI baseUrl, String resource) {
        return resolve(baseUrl, "v1", resource, true);
    }

    public static URI google(URI baseUrl, String resource) {
        return resolve(baseUrl, "v1beta", resource, false);
    }

    private static URI resolve(URI baseUrl, String version, String resource, boolean collapseV1) {
        if (baseUrl == null || !baseUrl.isAbsolute() || baseUrl.getHost() == null) {
            throw new IllegalArgumentException("baseUrl must be absolute");
        }
        String rawPath = baseUrl.getRawPath() == null ? "" : baseUrl.getRawPath();
        List<String> segments = new ArrayList<>();
        for (String segment : rawPath.split("/")) if (!segment.isBlank()) segments.add(segment);
        if (collapseV1) {
            while (!segments.isEmpty() && segments.get(segments.size() - 1).equals("v1")) {
                segments.remove(segments.size() - 1);
            }
        } else if (!segments.isEmpty() && (segments.get(segments.size() - 1).equals("v1")
                || segments.get(segments.size() - 1).equals("v1beta"))) {
            segments.remove(segments.size() - 1);
        }
        segments.add(version);
        for (String segment : resource.split("/")) if (!segment.isBlank()) segments.add(segment);
        String path = "/" + String.join("/", segments);
        try {
            return new URI(baseUrl.getScheme(), null, baseUrl.getHost(), baseUrl.getPort(), path, null, null);
        } catch (java.net.URISyntaxException exception) {
            throw new IllegalArgumentException("invalid provider endpoint", exception);
        }
    }
}
